/**
 * Filter active agents and prepare per-agent analysis items.
 * Each item carries agent metadata needed for cost + traces analysis.
 */
const agents = $input.first().json;
const agentList = Array.isArray(agents) ? agents : [agents];

const now = new Date();
const year = now.getFullYear();
const week = Math.ceil(((now - new Date(year, 0, 1)) / 86400000 + new Date(year, 0, 1).getDay() + 1) / 7);
const yearWeek = `${year}W${String(week).padStart(2, '0')}`;

return agentList
  .filter(a => a.is_active)
  .map(agent => ({
    json: {
      agent_slug: agent.slug,
      default_model: agent.default_model,
      safety_level: agent.safety_level,
      year_week: yearWeek,
    }
  }));

/**
 * WF_MODEL_ADVISORY — Analyze cost-quality delta.
 *
 * Combines cost simulation with 7-day performance snapshot to detect:
 * 1. Cost Overrun — agent costs exceed threshold, cheaper model with similar quality exists
 * 2. Quality Gap — agent quality is below acceptable threshold, better model recommended
 * 3. Efficiency Win — same quality achievable at lower cost tier
 *
 * Output: one item if advisory needed, empty if current config is optimal.
 */
const agent = $('Prepare Active Agents').item.json;
const costSim = $('Simulate Tier Cost').first().json;
const perfSnap = $('7-Day Performance Snapshot').first().json;

// Extract performance metrics
const avgOverall = perfSnap?.avg_overall ?? 0;
const errorRate = perfSnap?.error_rate ?? 0;
const totalEvents = perfSnap?.total_events ?? 0;

// Skip agents with insufficient data (< 50 events in 7 days)
if (totalEvents < 50) {
  return [];
}

const tiers = costSim?.tiers ?? {};
const tierEntries = Object.entries(tiers);

// Find current tier for this agent's model
let currentTierName = null;
let currentTierData = null;
for (const [tierName, tierData] of tierEntries) {
  if (tierData.model_id === agent.default_model) {
    currentTierName = tierName;
    currentTierData = tierData;
    break;
  }
}

if (!currentTierData) {
  // Model not in tier system — skip
  return [];
}

// Thresholds
const QUALITY_THRESHOLD = 0.65;     // Minimum acceptable quality score
const ERROR_RATE_THRESHOLD = 0.10;  // Max acceptable error rate
const COST_SAVING_THRESHOLD = 0.20; // Min 20% cost saving to recommend downgrade

const proposals = [];

// Check 1: Quality too low → recommend upgrade
if (avgOverall > 0 && avgOverall < QUALITY_THRESHOLD && errorRate < ERROR_RATE_THRESHOLD) {
  // Find next tier up with better expected quality
  const higherTiers = tierEntries.filter(([, td]) =>
    td.monthly_cost_usd > currentTierData.monthly_cost_usd
  );
  if (higherTiers.length > 0) {
    const [recTierName, recTierData] = higherTiers[0];
    proposals.push({
      agent_slug: agent.agent_slug,
      anomaly_key: `model_tier_recommendation_${agent.year_week}`,
      category: 'model',
      current_model: agent.default_model,
      current_monthly_cost: currentTierData.monthly_cost_usd,
      description: `Agent "${agent.agent_slug}" quality score (${avgOverall.toFixed(3)}) is below threshold (${QUALITY_THRESHOLD}). ` +
        `Recommending upgrade from ${currentTierName} (${agent.default_model}) to ${recTierName} (${recTierData.model_id}). ` +
        `Monthly cost delta: +$${(recTierData.monthly_cost_usd - currentTierData.monthly_cost_usd).toFixed(2)}.`,
      proposed_model: recTierData.model_id,
      proposed_monthly_cost: recTierData.monthly_cost_usd,
      quality_score: avgOverall,
      reason: 'quality_gap',
      risk_level: 'medium',
      title: `Upgrade ${agent.agent_slug} model for quality`,
    });
  }
}

// Check 2: High quality + high cost → recommend downgrade
if (avgOverall >= 0.85 && errorRate < 0.03) {
  const cheaperTiers = tierEntries.filter(([, td]) =>
    td.monthly_cost_usd < currentTierData.monthly_cost_usd
  );
  if (cheaperTiers.length > 0) {
    // Pick cheapest tier
    const [recTierName, recTierData] = cheaperTiers.sort((a, b) =>
      a[1].monthly_cost_usd - b[1].monthly_cost_usd
    )[0];
    const savingPct = (currentTierData.monthly_cost_usd - recTierData.monthly_cost_usd) / currentTierData.monthly_cost_usd;
    if (savingPct >= COST_SAVING_THRESHOLD) {
      proposals.push({
        agent_slug: agent.agent_slug,
        anomaly_key: `model_tier_recommendation_${agent.year_week}`,
        category: 'model',
        current_model: agent.default_model,
        current_monthly_cost: currentTierData.monthly_cost_usd,
        description: `Agent "${agent.agent_slug}" has high quality (${avgOverall.toFixed(3)}) with low error rate (${(errorRate * 100).toFixed(1)}%). ` +
          `Potential ${(savingPct * 100).toFixed(0)}% cost saving by downgrading from ${currentTierName} (${agent.default_model}) ` +
          `to ${recTierName} (${recTierData.model_id}). Monthly saving: $${(currentTierData.monthly_cost_usd - recTierData.monthly_cost_usd).toFixed(2)}.`,
        proposed_model: recTierData.model_id,
        proposed_monthly_cost: recTierData.monthly_cost_usd,
        quality_score: avgOverall,
        reason: 'efficiency_win',
        risk_level: 'low',
        title: `Downgrade ${agent.agent_slug} model to save cost`,
      });
    }
  }
}

// Check 3: Error rate spike → flag for review
if (errorRate >= ERROR_RATE_THRESHOLD) {
  proposals.push({
    agent_slug: agent.agent_slug,
    anomaly_key: `model_error_spike_${agent.year_week}`,
    category: 'reliability',
    current_model: agent.default_model,
    current_monthly_cost: currentTierData?.monthly_cost_usd ?? 0,
    description: `Agent "${agent.agent_slug}" error rate (${(errorRate * 100).toFixed(1)}%) exceeds threshold (${(ERROR_RATE_THRESHOLD * 100).toFixed(0)}%). ` +
      `Total events: ${totalEvents}, error count: ${Math.round(errorRate * totalEvents)}. ` +
      `Review model configuration and error patterns.`,
    proposed_model: agent.default_model,
    proposed_monthly_cost: currentTierData?.monthly_cost_usd ?? 0,
    quality_score: avgOverall,
    reason: 'error_spike',
    risk_level: 'high',
    title: `Review ${agent.agent_slug} — high error rate`,
  });
}

return proposals.map(p => ({ json: p }));

/**
 * WF_MODEL_ADVISORY — Aggregate results for logging/response.
 */
const items = $input.all();
const proposals = items.map(i => i.json);

return [{
  json: {
    workflow: 'WF_MODEL_ADVISORY',
    proposals_created: proposals.length,
    agents_analyzed: [...new Set(proposals.map(p => p.agent_slug || p.p_agent_slug))].length,
    completed_at: new Date().toISOString(),
    results: proposals,
  }
}];
